# Wind formulas used by the column definitions (same as the generator's)
u_weak(z) = z <= 25.0 ? 2.0 : z >= 1500.0 ? 10.0 : 2.0 + 8.0 * log(z / 25.0) / log(1500.0 / 25.0)
function s_bump(z; z1 = 4000.0, L = 750.0, c = 1.6e-5)
    z <= z1 && return 0.0
    z <= z1 + L && return 0.5 * c * (z - z1)^2
    if z <= z1 + 2 * L
        x = z - z1 - L
        return 0.5 * c * L^2 + c * L * x - 0.5 * c * x^2
    end
    return c * L^2
end

